/* The adversary: a second model running beside the spear that rates the
 * closed USER and TURN entries of the session log. It never acts and has no
 * nextvi access, only ratings; the spear sees them when a kind 1 checkpoint
 * opens. One background curl at a time, polled from the single threaded main
 * loop, portable OpenAI chat completions only: no grammar, json_schema or
 * response_format. Ratings are staged in memory and reach b-6 at that
 * checkpoint. b-9 logs raw replies, parsed lines, retries and errors for
 * observation; no adversary state is ever read back from it. */
#define ADV_RESULT_MAX 4000		/* RESULT body bytes sent per part */
#define ADV_ATTEMPTS 3			/* requests per batch, the first one */
#define ADV_BATCH_MAX 64		/* entries per request */
#define ADV_BATCH_BYTES (512 * 1024)	/* log bytes per request */
#define ADV_REPLY_MAX (4 << 20)		/* reply bytes kept */
#define ADV_LOG_MAX 5000		/* b-9 lines kept */

static char agent_adv_intro[] =
	"You are an adversarial reviewer of the session log of another model,\n"
	"the spear. You do not act and you have no access to the editor: you\n"
	"only rate. Read the entries listed under \"Entries:\" below, then rate\n"
	"each entry by the value it has for the work that follows it. Be\n"
	"strict: routine mechanics and repeated attempts rate 1 at most.\n"
	"A USER entry is what the user wrote. A TURN entry is one spear reply\n"
	"with its REASONING, the EX commands it ran and their RESULT bodies;\n"
	"a RESULT body may be truncated. Judge what an entry contributed, not\n"
	"the run as a whole.\n"
	"Reply with only the requested lines, one per entry and no other text,\n"
	"no heading and no code fence:\n"
	"N R sentence\n"
	"N is the entry number, R the rating, sentence one short sentence of\n"
	"justification.\n\n";

static struct {
	pid_t pid;		/* the curl child; 0 when idle */
	int out, err;		/* read ends of its pipes; -1 when idle */
	sbuf *ob, *eb;		/* what has been read from them */
	unsigned long *batch;	/* entry numbers of the running request */
	int nbatch, attempt;	/* batch size, requests made for it */
	char *prompt;		/* its user message, kept for a retry */
	char *prev;		/* previous reply, sent as an assistant turn */
	char hdpath[64];	/* header file handed to curl */
	int disabled;		/* endpoint unreachable: off for the session */
} agent_adv = {0, -1, -1};

/* A staged rating: not in b-6 until a kind 1 checkpoint merges it. */
struct agent_adv_rating { unsigned long n; int rate; char *text; };
static struct agent_adv_rating *agent_adv_staged;
static int agent_adv_nstaged;
/* Entries given up on after ADV_ATTEMPTS malformed answers, so that they are
 * not sent forever. */
static unsigned long *agent_adv_gaveup;
static int agent_adv_ngaveup;

/* Append s to b-9, keeping the file bounded, and let the session save it:
 * inside a tool call agent_sync defers the write to agent_sync_pending. */
static void agent_adv_log(const char *s)
{
	struct lbuf *lb = tempbufs[8].lb;
	int n = lbuf_len(lb);
	if (!*s)
		return;
	preserve(int, agent_syncing, agent_syncing = 1;)
	if (n > ADV_LOG_MAX) {
		lbuf_edit(lb, NULL, 0, n - ADV_LOG_MAX / 2, 0, 0);
		temp_pos(8, lbuf_len(lb) - 1, 0, 0);
		if (ex_buf == tempbufs+8) {
			exbuf_load(ex_buf)
		}
	}
	temp_write(8, (char *)s);
	restore(agent_syncing)
	agent_sync(lb);
}

/* A b-9 line with a printf format. */
static void agent_adv_note(const char *fmt, ...)
{
	char ln[512];
	va_list ap;
	va_start(ap, fmt);
	vsnprintf(ln, sizeof(ln), fmt, ap);
	va_end(ap);
	ln[sizeof(ln)-1] = '\''\0'\'';
	agent_adv_log(ln);
}

/* Whether set holds n. */
static int agent_adv_has(unsigned long *set, int cnt, unsigned long n)
{
	for (int i = 0; i < cnt; i++)
		if (set[i] == n)
			return 1;
	return 0;
}

/* Drop n from set, or all of it with n ~0. */
static void agent_adv_drop(unsigned long *set, int *cnt, unsigned long n)
{
	int i = 0;
	while (i < *cnt)
		if (set[i] == n || n == ~0UL)
			set[i] = set[--*cnt];
		else
			i++;
}

/* Remember n as given up on, so the adversary is not asked for it again. */
static void agent_adv_add(unsigned long **set, int *cnt, unsigned long n)
{
	if (agent_adv_has(*set, *cnt, n))
		return;
	*set = erealloc(*set, (*cnt + 1) * sizeof(**set));
	(*set)[(*cnt)++] = n;
}

/* Stage a rating for entry n, replacing a staged one: the last line wins. */
static void agent_adv_stage(unsigned long n, int rate, const char *text)
{
	struct agent_adv_rating *r = NULL;
	int i;
	for (i = 0; i < agent_adv_nstaged; i++)
		if (agent_adv_staged[i].n == n) {
			r = agent_adv_staged + i;
			break;
		}
	if (!r) {
		agent_adv_staged = erealloc(agent_adv_staged,
			(agent_adv_nstaged + 1) * sizeof(*agent_adv_staged));
		r = agent_adv_staged + agent_adv_nstaged++;
		r->n = n;
		r->text = NULL;
	}
	free(r->text);
	r->rate = rate;
	r->text = sdup(text, strlen(text));
}

/* Forget the running request, staging nothing: its entries are collected
 * again later. Staged ratings and the given-up set are kept. */
static void agent_adv_batch_drop(void)
{
	free(agent_adv.batch);
	agent_adv.batch = NULL;
	agent_adv.nbatch = 0;
	agent_adv.attempt = 0;
	free(agent_adv.prompt);
	agent_adv.prompt = NULL;
	free(agent_adv.prev);
	agent_adv.prev = NULL;
}

/* Stop the curl child and forget its request. With job 0 agent_killtree
 * never touches the terminal'\''s foreground job. */
static void agent_adv_kill(void)
{
	if (agent_adv.pid > 0) {
		agent_killtree(agent_adv.pid, 0, 0);
		waitpid(agent_adv.pid, NULL, 0);
		agent_adv.pid = 0;
	}
	if (agent_adv.out >= 0)
		close(agent_adv.out);
	if (agent_adv.err >= 0)
		close(agent_adv.err);
	agent_adv.out = agent_adv.err = -1;
	if (agent_adv.ob) {
		sbuf_free(agent_adv.ob)
		agent_adv.ob = NULL;
	}
	if (agent_adv.eb) {
		sbuf_free(agent_adv.eb)
		agent_adv.eb = NULL;
	}
	if (*agent_adv.hdpath) {
		unlink(agent_adv.hdpath);
		*agent_adv.hdpath = '\''\0'\'';
	}
	agent_adv_batch_drop();
}

/* A copy of agent_config for the adversary'\''s own endpoint: portable OpenAI
 * chat completions only, so the body carries messages and nothing else the
 * spear'\''s request owns. */
static cJSON *agent_adv_config(void)
{
	cJSON *req = cJSON_ParseWithOpts(adv_request_extra, NULL, 1);
	if (!cJSON_IsObject(req) || !adv_api_key || !*adv_api_key ||
			strpbrk(adv_api_key, "\r\n") || !adv_endpoint ||
			(strncmp(adv_endpoint, "http://", 7) &&
			strncmp(adv_endpoint, "https://", 8)) ||
			adv_timeout <= 0) {
		cJSON_Delete(req);
		return NULL;
	}
	const char *owned[] = {"messages", "tools", "stream", "tool_choice",
		"response_format"};
	for (int i = 0; i < LEN(owned); i++)
		while (cJSON_GetObjectItem(req, owned[i]))
			cJSON_DeleteItemFromObject(req, owned[i]);
	return req;
}

/* The span of entry n among spans, or NULL. */
static struct agent_span *agent_adv_span(struct agent_span *spans, int cnt,
		unsigned long n)
{
	for (int k = 0; k < cnt; k++)
		if (spans[k].n == n)
			return spans + k;
	return NULL;
}

/* Whether span is closed: a USER body has its END line, and the last entry
 * of the log has none only while it is still being written. A part of the
 * open TURN is never sent. */
static int agent_adv_closed(struct agent_span *s, int last)
{
	if (s->role == AE_TURN)
		return !(agent_turn[1] && s->n == agent_turn[1]) &&
			(!last || !*s->open);
	return s->close >= 0 || (!last || !*s->open);
}

/* lb lines beg through end-1 into sb, capping the body at max bytes; with
 * max 0 all of it. A cut body gets a note of the bytes dropped. */
static void agent_adv_lines(sbuf *sb, struct lbuf *lb, int beg, int end,
		int max)
{
	int all = 0, kept = 0, cut = 0, n;
	char msg[96];
	for (int i = beg; i < end; i++) {
		n = strlen(lb->ln[i]);
		all += n;
		if (max && kept + n > max) {
			if (kept < max) {
				sbuf_mem(sb, lb->ln[i], max - kept)
				sbuf_chr(sb, '\''\n'\'')
				kept = max;
			}
			cut = 1;
			continue;
		}
		kept += n;
		sbuf_str(sb, lb->ln[i])
	}
	if (cut) {
		snprintf(msg, sizeof(msg), "[... %d bytes truncated]\n",
			all - kept);
		sbuf_str(sb, msg)
	}
}

/* Entry s of lb into sb: its lines verbatim, only a RESULT body capped at
 * ADV_RESULT_MAX bytes. Headers and END lines come from the buffer, so the
 * adversary sees exactly what the log holds. */
static void agent_adv_entry(sbuf *sb, struct lbuf *lb, struct agent_span *s)
{
	struct agent_part *parts = NULL;
	int pcnt = s->role == AE_TURN ? agent_parts(lb, s, &parts) : 0, to;
	if (!pcnt) {
		agent_adv_lines(sb, lb, s->beg,
			s->close >= 0 ? s->close + 1 : s->end, 0);
		free(parts);
		return;
	}
	for (int p = 0; p < pcnt; p++) {
		sbuf_str(sb, lb->ln[parts[p].beg])
		to = parts[p].close > 0 ? parts[p].close : parts[p].end;
		agent_adv_lines(sb, lb, parts[p].beg + 1, to,
			parts[p].role == AP_RESULT ? ADV_RESULT_MAX : 0);
		if (parts[p].close > 0)
			sbuf_str(sb, lb->ln[parts[p].close])
	}
	free(parts);
}

/* Numbers of closed USER and TURN entries the adversary has not rated: not
 * in b-6, not staged, not asked for, not given up on, at or above the last
 * compaction. Returns the count and sets *nums, which the caller frees. */
static int agent_adv_collect(unsigned long **nums)
{
	struct agent_span *spans;
	struct lbuf *lb = tempbufs[3].lb;
	unsigned long floor = agent_epoch_floor(), n;
	int cnt = agent_spans(&spans), last = cnt - 1, nr = 0, rate, row;
	*nums = emalloc((cnt ? cnt : 1) * sizeof(**nums));
	for (int k = 0; k < cnt && nr < ADV_BATCH_MAX; k++) {
		if ((spans[k].role != AE_USER && spans[k].role != AE_TURN) ||
				spans[k].n < floor ||
				!agent_adv_closed(spans + k, k == last) ||
				agent_note(spans[k].n, &rate, &row) ||
				agent_adv_has(agent_adv_gaveup, agent_adv_ngaveup,
					spans[k].n) ||
				agent_adv_has(agent_adv.batch, agent_adv.nbatch,
					spans[k].n))
			continue;
		n = spans[k].n;
		for (int i = 0; i < agent_adv_nstaged; i++)
			if (agent_adv_staged[i].n == n)
				goto next;
		/* Stop the batch at the size cap; the rest waits for the next. */
		if (nr && lb->ln[spans[k].beg]) {
			sbuf_smake(sb, 1024)
			agent_adv_entry(sb, lb, spans + k);
			if (sb->s_n > ADV_BATCH_BYTES) {
				free(sb->s);
				break;
			}
			free(sb->s);
		}
		(*nums)[nr++] = n;
		next:;
	}
	free(spans);
	return nr;
}

/* Its context: the instructions, then its previous ratings, live ones of b-6
 * and the staged ones not in the log yet, then the entries of this batch and
 * the lines it must answer with. */
static char *agent_adv_prompt(unsigned long *nums, int nr)
{
	struct lbuf *lb = tempbufs[3].lb, *nb = tempbufs[5].lb;
	struct agent_span *spans;
	unsigned long floor = agent_epoch_floor(), n;
	int cnt = agent_spans(&spans), rate;
	char head[64];
	sbuf_smake(sb, 4096)
	sbuf_str(sb, agent_adv_intro)
	sbuf_str(sb, agent_rating_scale)
	sbuf_str(sb, "\nPrevious ratings:\n")
	for (int i = 0; i < lbuf_len(nb); i++)
		if (agent_note_line(nb->ln[i], &n, &rate) && n >= floor)
			sbuf_str(sb, nb->ln[i])
	for (int i = 0; i < agent_adv_nstaged; i++) {
		if (agent_adv_staged[i].n < floor)
			continue;
		snprintf(head, sizeof(head), "%lu %d ", agent_adv_staged[i].n,
			agent_adv_staged[i].rate);
		sbuf_str(sb, head)
		if (agent_adv_staged[i].text)
			sbuf_str(sb, agent_adv_staged[i].text)
		sbuf_chr(sb, '\''\n'\'')
	}
	sbuf_str(sb, "\nEntries:\n")
	for (int i = 0; i < nr; i++) {
		struct agent_span *s = agent_adv_span(spans, cnt, nums[i]);
		if (!s)
			continue;
		agent_adv_entry(sb, lb, s);
		sbuf_chr(sb, '\''\n'\'')
	}
	sbuf_str(sb, "Rate every entry listed, replying only with these lines:\n")
	for (int i = 0; i < nr; i++) {
		snprintf(head, sizeof(head), "%lu R sentence\n", nums[i]);
		sbuf_str(sb, head)
	}
	free(spans);
	sbufn_ret(sb, sb->s)
}

/* The read end of a pipe the main loop must never wait on. */
static void agent_adv_nb(int fd)
{
	int fl = fcntl(fd, F_GETFL, 0);
	if (fl >= 0)
		fcntl(fd, F_SETFL, fl | O_NONBLOCK);
}

/* Send req to the adversary'\''s endpoint with a background curl: its stdin is
 * a file, its output and error go to pipes the main loop drains. Unlike
 * agent_http this never waits, so the reply is read across main loop
 * iterations; the pid stays out of agent_jobs, whose entries agent_reap
 * collects and would take the exit status from. Returns 0 on a failure that
 * leaves nothing running. */
static int agent_adv_start(cJSON *req)
{
	char hdrpath[] = "/tmp/nextvi-header-XXXXXX", timeout[32], hdrarg[80];
	int fd = mkstemp(hdrpath), out[2] = {-1, -1}, err[2] = {-1, -1};
	FILE *in = tmpfile();
	pid_t pid;
	char *body = req ? cJSON_PrintUnformatted(req) : NULL;
	sbuf_smake(hdr, 128)
	if (fd < 0 || !in || !body || agent_writeall(fd, hdr->s, hdr->s_n) ||
			agent_writeall(fileno(in), body, strlen(body))) {
		if (fd >= 0) {
			close(fd);
			unlink(hdrpath);
		}
		if (in)
			fclose(in);
		free(body);
		free(hdr->s);
		return 0;
	}
	close(fd);
	snprintf(timeout, sizeof(timeout), "%d", adv_timeout);
	sprintf(hdrarg, "@%s", hdrpath);
	char *argv[] = {
		"curl", "--disable", "--silent", "--show-error",
		"--fail-with-body", "--max-time", timeout, "--header", hdrarg,
		"--header", "Content-Type: application/json",
		"--data-binary", "@-", "--url", adv_endpoint, NULL
	};
	if (pipe(out) || pipe(err)) {
		if (out[0] >= 0)
			close(out[0]);
		if (out[1] >= 0)
			close(out[1]);
		if (err[0] >= 0)
			close(err[0]);
		if (err[1] >= 0)
			close(err[1]);
		fclose(in);
		unlink(hdrpath);
		free(body);
		free(hdr->s);
		return 0;
	}
	pid = fork();
	if (!pid) {
		if (setpgid(0, 0) < 0)
			_exit(127);
		dup2(fileno(in), STDIN_FILENO);
		dup2(out[1], STDOUT_FILENO);
		dup2(err[1], STDERR_FILENO);
		close(out[0]);
		close(out[1]);
		close(err[0]);
		close(err[1]);
		fclose(in);
		execvp(argv[0], argv);
		_exit(127);
	}
	fclose(in);
	close(out[1]);
	close(err[1]);
	free(body);
	if (pid < 0) {
		close(out[0]);
		close(err[0]);
		unlink(hdrpath);
		free(hdr->s);
		return 0;
	}
	setpgid(pid, pid);
	agent_adv_nb(out[0]);
	agent_adv_nb(err[0]);
	agent_adv.pid = pid;
	agent_adv.out = out[0];
	agent_adv.err = err[0];
	if (agent_adv.ob) {
		sbuf_free(agent_adv.ob)
		agent_adv.ob = NULL;
	}
	if (agent_adv.eb) {
		sbuf_free(agent_adv.eb)
		agent_adv.eb = NULL;
	}
	sbuf_make(agent_adv.ob, 4096)
	sbuf_make(agent_adv.eb, 4096)
	snprintf(agent_adv.hdpath, sizeof(agent_adv.hdpath), "%s", hdrpath);
	free(hdr->s);
	return 1;
}

/* Whether n has a staged rating. */
static int agent_adv_staged_has(unsigned long n)
{
	for (int i = 0; i < agent_adv_nstaged; i++)
		if (agent_adv_staged[i].n == n)
			return 1;
	return 0;
}

/* Stage every "N R sentence" line of reply: leading whitespace, '\''-'\'', '\''*'\'',
 * '\''>'\'' and backticks are stripped, a line that does not match is ignored, N
 * must be in the batch and a repeated N keeps its last line. */
static void agent_adv_parse(const char *reply)
{
	char ln[2048], *p, *q;
	const char *s = reply;
	unsigned long n;
	int len;
	while (s && *s) {
		const char *nl = strchr(s, '\''\n'\'');
		len = nl ? (int)(nl - s) : (int)strlen(s);
		if (len > (int)sizeof(ln) - 1)
			len = sizeof(ln) - 1;
		memcpy(ln, s, len);
		ln[len] = '\''\0'\'';
		s = nl ? nl + 1 : NULL;
		p = ln;
		while (*p == '\'' '\'' || *p == '\''\t'\'' || *p == '\''-'\'' || *p == '\''*'\'' ||
				*p == '\''>'\'' || *p == '\''`'\'')
			p++;
		n = strtoul(p, &q, 10);
		if (q == p || !agent_adv_has(agent_adv.batch, agent_adv.nbatch, n))
			continue;
		while (*q == '\'' '\'' || *q == '\''\t'\'' || *q == '\'':'\'' || *q == '\''='\'')
			q++;
		if (!isdigit((unsigned char)*q) || q[1] > '\'' '\'')
			continue;
		if (*q <= '\''3'\'')
			agent_adv_stage(n, *q - '\''0'\'', q + 1 +
				strspn(q + 1, " \t"));
	}
}

/* The batch numbers with no staged rating; sets *set, which the caller
 * frees, and returns how many they are. */
static int agent_adv_missing(unsigned long **set)
{
	int n = 0;
	*set = NULL;
	for (int i = 0; i < agent_adv.nbatch; i++)
		if (!agent_adv_staged_has(agent_adv.batch[i]))
			n++;
	if (!n)
		return 0;
	*set = emalloc(n * sizeof(**set));
	n = 0;
	for (int i = 0; i < agent_adv.nbatch; i++)
		if (!agent_adv_staged_has(agent_adv.batch[i]))
			(*set)[n++] = agent_adv.batch[i];
	return n;
}
/* Ask the adversary for the batch: its instructions, the prompt kept from
 * the first request and, on a retry, its previous answer as an assistant
 * turn and a correction naming only the numbers still wanted. */
static int agent_adv_request(int retry, unsigned long *miss, int nmiss)
{
	cJSON *req = agent_adv_config(), *msgs;
	char num[32];
	sbuf_smake(sys, 2048)
	sbuf_smake(corr, 256)
	if (!req) {
		agent_adv.disabled = 1;
		agent_adv_note("invalid adversary configuration; :adv off");
		return 0;
	}
	sbuf_str(sys, agent_adv_intro)
	sbuf_str(sys, agent_rating_scale)
	sbuf_nul(sys)
	msgs = cJSON_CreateArray();
	cJSON_AddItemToArray(msgs, agent_msg("system", sys->s));
	cJSON_AddItemToArray(msgs, agent_msg("user", agent_adv.prompt ?
		agent_adv.prompt : ""));
	if (retry) {
		cJSON_AddItemToArray(msgs, agent_msg("assistant",
			agent_adv.prev ? agent_adv.prev : ""));
		sbuf_str(corr, "Missing ratings for")
		for (int i = 0; i < nmiss; i++) {
			snprintf(num, sizeof(num), " %s%lu", i ? "," : "", miss[i]);
			sbuf_str(corr, num)
		}
		sbuf_str(corr, "; reply only those lines, one per entry, and no "
			"other text.")
		sbuf_nul(corr)
		cJSON_AddItemToArray(msgs, agent_msg("user", corr->s));
	}
	cJSON_AddItemReferenceToObject(req, "messages", msgs);
	if (!agent_adv_start(req)) {
		cJSON_Delete(msgs);
		cJSON_Delete(req);
		free(sys->s);
		free(corr->s);
		return 0;
	}
	cJSON_Delete(msgs);
	cJSON_Delete(req);
	free(sys->s);
	free(corr->s);
	return 1;
}

/* The reply is in: read it, log it, stage what parses and ask again for the
 * rest while attempts are left. */
static void agent_adv_finish(int st)
{
	cJSON *root, *msg;
	char *body = agent_adv.ob && agent_adv.ob->s ? agent_adv.ob->s : NULL;
	char *err = agent_adv.eb && agent_adv.eb->s ? agent_adv.eb->s : NULL;
	char *content = NULL, note[256];
	unsigned long *miss = NULL;
	int nmiss;
	if (st == 7 || (err && (strstr(err, "Couldn'\''t connect") ||
			strstr(err, "Could not resolve")))) {
		ex_print("adversary endpoint unreachable; :adv is off for this "
			"session", msg_ft);
		agent_adv.disabled = 1;
		agent_adv_kill();
		return;
	}
	if (st && (!body || !*body)) {
		agent_adv_note("request failed, status %d%s%s", st,
			err && *err ? ": " : "", err ? err : "");
		agent_adv_batch_drop();
		return;
	}
	root = cJSON_ParseWithOpts(body ? body : "", NULL, 1);
	if (cJSON_GetObjectItem(root, "error")) {
		agent_adv_note("endpoint error: %s",
			cJSON_GetStringValue(cJSON_GetObjectItem(
				cJSON_GetObjectItem(root, "error"), "message")));
		cJSON_Delete(root);
		agent_adv_batch_drop();
		return;
	}
	msg = agent_reply(root);
	if (cJSON_IsString(cJSON_GetObjectItem(msg, "content")))
		content = cJSON_GetObjectItem(msg, "content")->valuestring;
	agent_adv_note("--- reply, attempt %d of %d, status %d ---",
		agent_adv.attempt, ADV_ATTEMPTS, st);
	agent_adv_log(content ? content : "");
	agent_adv_parse(content);
	nmiss = agent_adv_missing(&miss);
	if (!nmiss)
		agent_adv_note("staged %d rating%s", agent_adv.nbatch,
			agent_adv.nbatch == 1 ? "" : "s");
	else if (agent_adv.attempt < ADV_ATTEMPTS) {
		snprintf(note, sizeof(note), "missing");
		for (int i = 0; i < nmiss; i++)
			snprintf(note + strlen(note), sizeof(note) - strlen(note),
				" %lu", miss[i]);
		agent_adv_note("%s; asking again", note);
		free(agent_adv.prev);
		agent_adv.prev = content ? sdup(content, strlen(content)) : NULL;
		if (agent_adv_request(1, miss, nmiss)) {
			free(miss);
			cJSON_Delete(root);
			return;
		}
		agent_adv_note("could not ask again; leaving them unrated");
	} else
		agent_adv_note("still missing %d after %d attempts; giving up",
			nmiss, ADV_ATTEMPTS);
	for (int i = 0; i < nmiss; i++)
		agent_adv_add(&agent_adv_gaveup, &agent_adv_ngaveup, miss[i]);
	free(miss);
	cJSON_Delete(root);
	agent_adv_batch_drop();
}

/* Drain the running curl without ever waiting: read what is there, and once
 * both pipes are closed and the child is gone, handle the reply. */
static void agent_adv_poll(void)
{
	struct pollfd fds[2];
	unsigned long *nums = NULL;
	char buf[4096];
	int st = 0, live = 0, nr;
	if (agent_adv.disabled || !xadv) {
		agent_adv_dirty = 0;
		return;
	}
	if (agent_adv.pid > 0) {
		for (int i = 0; i < 2; i++) {
			fds[i].fd = i ? agent_adv.err : agent_adv.out;
			fds[i].events = POLLIN;
			fds[i].revents = 0;
			if (fds[i].fd < 0)
				continue;
			nr = poll(fds + i, 1, 0);
			if (nr < 0) {
				if (errno != EINTR) {
					close(fds[i].fd);
					*(i ? &agent_adv.err : &agent_adv.out) = -1;
				}
				continue;
			}
			if (!nr || !(fds[i].revents & (POLLIN | POLLHUP | POLLERR)))
				continue;
			nr = read(fds[i].fd, buf, sizeof(buf));
			if (nr > 0) {
				sbuf *d = i ? agent_adv.eb : agent_adv.ob;
				if (d->s_n < ADV_REPLY_MAX)
					sbuf_mem(d, buf, MIN(nr,
						ADV_REPLY_MAX - d->s_n))
			} else if (!nr || errno != EINTR) {
				close(fds[i].fd);
				*(i ? &agent_adv.err : &agent_adv.out) = -1;
			}
		}
		for (int i = 0; i < 2; i++)
			live += (i ? agent_adv.err : agent_adv.out) >= 0;
		if (live || waitpid(agent_adv.pid, &st, WNOHANG) != agent_adv.pid)
			return;
		agent_adv.pid = 0;
		st = WIFEXITED(st) ? WEXITSTATUS(st) : 128 + WTERMSIG(st);
		agent_adv_finish(st);
		/* the reply buffers stay: a retry replaced them, else a kill or
		   the next request frees them */
		return;
	}
	/* Nothing runs: start the next batch when the log is the one being
	 * written, no pack or checkpoint holds it and the editor is idle. */
	if (!agent_ready || agent_packing || agent_logbuf != 3 ||
			agent_cancel || agent_pause)
		return;
	nr = agent_adv_collect(&nums);
	agent_adv_dirty = 0;
	if (!nr) {
		free(nums);
		return;
	}
	agent_adv.batch = nums;
	agent_adv.nbatch = nr;
	agent_adv.attempt = 1;
	agent_adv.prompt = agent_adv_prompt(nums, nr);
	agent_adv_note("--- asking for %d entr%s ---", nr,
		nr == 1 ? "y" : "ies");
	if (!agent_adv_request(0, nums, nr)) {
		agent_adv_note("could not start the request; trying later");
		agent_adv_batch_drop();
		agent_adv_dirty = 1;
	}
}

/* Whether the main loop must not sit in poll(-1): a curl to drain, or
 * entries that closed and have not been looked at yet. The flag lets an
 * idle editor wait for a keystroke instead of reparsing b-4 every 200 ms. */
static int agent_adv_pending(void)
{
	return agent_adv.pid > 0 || (agent_adv_dirty && xadv &&
		!agent_adv.disabled);
}

/* A kind 1 checkpoint opens: the spear is about to rate, so the staged
 * ratings go into b-6 first and only for entries it has not rated itself.
 * agent_note_set never trims, so a 0 here removes nothing. */
static void agent_adv_merge(void)
{
	struct agent_span *spans;
	struct lbuf *lb = tempbufs[5].lb;
	unsigned long floor = agent_epoch_floor();
	int cnt = agent_spans(&spans), rate, row, n = 0;
	if (!agent_adv_nstaged) {
		free(spans);
		return;
	}
	preserve(int, agent_syncing, agent_syncing = 1;)
	for (int i = 0; i < agent_adv_nstaged; i++) {
		if (agent_adv_staged[i].n < floor ||
				!agent_span_rated(spans, cnt, agent_adv_staged[i].n) ||
				agent_note(agent_adv_staged[i].n, &rate, &row))
			continue;
		agent_note_set(agent_adv_staged[i].n, agent_adv_staged[i].rate,
			agent_adv_staged[i].text ? agent_adv_staged[i].text : "");
		n++;
	}
	restore(agent_syncing)
	free(spans);
	for (int i = 0; i < agent_adv_nstaged; i++)
		free(agent_adv_staged[i].text);
	agent_adv_nstaged = 0;
	if (n) {
		agent_adv_note("merged %d staged rating%s into b-6", n,
			n == 1 ? "" : "s");
		agent_sync(lb);
	}
}

/* A checkpoint ended or the log was compacted or resumed: entries the spear
 * no longer has are dropped from the staged and given-up sets, so the
 * adversary is asked only about what is still live. */
static void agent_adv_resync(void)
{
	struct agent_span *spans;
	unsigned long floor = agent_epoch_floor();
	int cnt = agent_spans(&spans), i = 0, n = 0;
	while (i < agent_adv_nstaged) {
		if (agent_adv_staged[i].n < floor ||
				!agent_span_rated(spans, cnt, agent_adv_staged[i].n)) {
			free(agent_adv_staged[i].text);
			agent_adv_staged[i] = agent_adv_staged[--agent_adv_nstaged];
			n++;
			continue;
		}
		i++;
	}
	for (i = 0; i < agent_adv_ngaveup; ) {
		if (agent_adv_gaveup[i] < floor ||
				!agent_span_rated(spans, cnt, agent_adv_gaveup[i]))
			agent_adv_drop(agent_adv_gaveup, &agent_adv_ngaveup,
				agent_adv_gaveup[i]);
		else
			i++;
	}
	free(spans);
	if (n)
		agent_adv_note("dropped %d staged rating%s no longer live", n,
			n == 1 ? "" : "s");
}

