+/* Wait for terminal input. The wait is cut short while the adversary has a
+ * curl running, so the main loop can drain its pipes, and while entries
+ * have closed for it to review: a single poll(-1) would leave the last turn
+ * of a run unrated until the user types. */
+static int term_wait(void)
+{
+	int n;
+	if (!agent_adv_pending())
+		return poll(&term_ufd, 1, -1);
+	while (!(n = poll(&term_ufd, 1, 200)))
+		agent_adv_poll();
+	return n;
+}
